I just use a custom context class with explicitly declared types of its scene, session and state, like this:

```typescript
// Context.ts

import { Context as Telegraf_Context } from 'telegraf'
import type { Session } from './Session.js'
import type { State } from './State.js'

export class Context extends Telegraf_Context {
  public static assert(context: Telegraf_Context | Context): asserts context is Context {
    if (!context.state._contextAssert) throw new Error()
  }

  declare public readonly scene: Scenes.SceneContextScene<Context>
  public session?: Session // set it yourself whenever appropriate
  declare public readonly state: State
}
```

