// Tg.ts

import { Telegraf } from 'telegraf'
import { Context } from './Context.js'

export class Tg {
  private readonly telegraf: Telegraf<Context>

  public constructor(readonly TG_BOT_TOKEN: string) {
    this.telegraf = new Telegraf<Context>(TG_BOT_TOKEN, { contextType: Context })
    this.telegraf.use(this.middlewareFn)

    this.telegraf.on(message(), async (context, next) => {
      Context.assert(context) // sometimes required because of inconsistent `context` typings
      // ...
    }
  }

  private readonly middlewareFn: MiddlewareFn<Context> = async (context, next) => { // bound to `this` in case you also want to manage its properties here
    context.state._contextAssert = true
    return next()
  }
}
