I dont like classes, so its a function

First, here are the types

```ts
import { Context, Scenes } from "telegraf";

export interface MyState {
	user: {
		name: string;
	};
    //...add more fields for your state here
}
interface MySessionData extends Scenes.SceneSessionData {
	state: MyState;
}

export interface MyContext extends Context {
	session: Scenes.SceneSession<MySessionData>;
	scene: Scenes.SceneContextScene<MyContext, MySessionData>;
}
```

Then, here is the state

```ts
export const DEFAULT_STATE:MyState = {
    user: {
        name: 'John'
        //add fields to match your interface
    }
}

const isObj = (v: unknown): v is Record<string, unknown> =>
	typeof v === "object" && v !== null && !Array.isArray(v);

function deepDefaults<T extends Record<string, any>>(
	target: T,
	defaults: T,
): T {
	for (const k of Object.keys(defaults) as (keyof T)[]) {
		const dv = defaults[k],
			tv = target[k];
		if (tv === undefined) {
			target[k] = isObj(dv)
				? ({ ...dv } as T[typeof k])
				: Array.isArray(dv)
				? ([...(dv as any[])] as T[typeof k])
				: dv;
		} else if (isObj(tv) && isObj(dv)) {
			deepDefaults(tv as any, dv as any);
		}
	}
	return target;
}

export const State = (ctx: MyContext): MyState => {
	const sc = (ctx.session.__scenes ??= {
		state: structuredClone(DEFAULT_STATE),
	});
	const st = (sc.state ??= structuredClone(DEFAULT_STATE));
	return deepDefaults(st, DEFAULT_STATE);
};
```

Then, where your instance of the bot is: 

```ts
bot.use(
	session({
		defaultSession: () => ({
			__scenes: {
				state: structuredClone(DEFAULT_STATE),
			},
		}),
	}),
);
bot.use(stage.middleware());
```

Now, you always read and write to your state via `State(ctx)`

```ts
REPAIR_COLLECT_NAME.on(message("text"), async (ctx) => {
	State(ctx).user.name = ctx.message.text; //with Intellisense 

	await ctx.reply(`Nice to meet you, ${State(ctx).user.name}!`);

	ctx.scene.enter(RepairSceneIDs.COLLECT_ADDRESS, State(ctx)); //pass it to next scene if you want it to preserve
});
```

